FOR t = 1..T:
    draw N; x0 <- ceil(sqrt N)
    vals <- { (x0 + j)^2 - N : j random }
    rnd  <- { uniform integer near v : v in vals }
    QRbase <- {2} U { p <= B : (N|p) = +1 }
    rate_x2[t]  <- frac of vals that are B-smooth
    rate_rnd[t] <- frac of rnd that are B-smooth
    rate_half[t]<- frac of rnd that are QRbase-smooth
RETURN means, ratios, decile spread of rate_x2

