"""Monte Carlo protocol: smoothness of x^2 - N versus random integers."""
from __future__ import annotations
import math
import random
from typing import Dict, List, Sequence


def primes_up_to(n: int) -> List[int]:
    s = bytearray([1]) * (n + 1); s[0] = s[1] = 0
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i::i] = bytearray(len(s[i * i::i]))
    return [i for i in range(n + 1) if s[i]]


def smooth(v: int, base: Sequence[int]) -> bool:
    v = abs(v)
    for p in base:
        while v % p == 0:
            v //= p
        if v == 1:
            return True
    return v == 1


def experiment(seed: int = 20260821, n_count: int = 30, per_n: int = 1000,
               digits: int = 14, bound: int = 600) -> Dict[str, float]:
    rng = random.Random(seed)
    base = primes_up_to(bound)
    x2: List[float] = []; rnd: List[float] = []; half: List[float] = []
    for _ in range(n_count):
        n = rng.randrange(10 ** (digits - 1), 10 ** digits)
        root = math.isqrt(n) + 1
        vals = [(root + rng.randrange(4 * per_n)) ** 2 - n for _ in range(per_n)]
        rv = [rng.randrange(v // 2, 3 * v // 2 + 2) for v in vals]
        qr_base = [2] + [p for p in base[1:] if pow(n % p, (p - 1) // 2, p) == 1]
        excl = [p for p in base if p not in set(qr_base)]
        x2.append(sum(smooth(v, base) for v in vals) / per_n)
        rnd.append(sum(smooth(v, base) for v in rv) / per_n)
        half.append(sum(smooth(v, qr_base) and all(v % p for p in excl) for v in rv) / per_n)
    m = lambda xs: sum(xs) / len(xs)
    return {"rate_x2": m(x2), "rate_random": m(rnd), "rate_qr_half": m(half),
            "ratio_x2_over_random": m(x2) / m(rnd),
            "deficit_qr_half": m(x2) / max(m(half), 1e-12)}


if __name__ == "__main__":
    print(experiment())
